KG42.register("edges-792edf001d521df41daed59e",{"id":"S-4d0d2733b108456a","source":"COMP-bf4a00350a51bde7","type":"implies","target":"COMP-a607cc256fbfc1eb","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["19-two_stage_battery_sharing"],"assertions":[{"id":"19-two_stage_battery_sharing::v141-c-R007::E::v141-c-R007-E002","paper":"19-two_stage_battery_sharing","rule_id":"v141-c-R007","rule_ref":"19-two_stage_battery_sharing::v141-c-R007","record":{"edge_id":"v141-c-R007-E002","source":"pricing.local","target":"settlement.payment","type":"implies","constraint_ids":["v141-c-R007-C003","v141-c-R007-C004","v141-c-R007-C005","v141-c-R007-C006"],"evidence_ids":["v141-b-g02-E23","v141-b-g03-E13","v141-b-g04-E10","v141-b-g04-E15","v141-b-g04-E17"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R007-C003","v141-c-R007-C004","v141-c-R007-C005","v141-c-R007-C006"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-bf4a00350a51bde7","target":"COMP-a607cc256fbfc1eb","source_occurrence_id":"19-two_stage_battery_sharing::v141-c-R007::V::pricing.local","target_occurrence_id":"19-two_stage_battery_sharing::v141-c-R007::V::settlement.payment","source_unit_id":"19-two_stage_battery_sharing::v141-a-M01::pricing.local","target_unit_id":"19-two_stage_battery_sharing::v141-a-M01::settlement.payment","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Consumer electricity bills under P2P sharing compared with P2G trading. | Customer billing in the proposed two-stage P2P sharing arrangement. | Electricity-bill payments and repayments of prosumers and consumers contracted with the ESC. | Individual customer settlement in the ESC-operated P2P sharing community. | Individual prosumer and consumer financial outcomes under modified SDR pricing compared with conventional P2G trading. | Prosumer electricity-bill values in the reported financial assessment. | The reported sensitivity evaluation across the studied penetration levels of PV battery systems. | The source’s explanation of prosumer income and consumer benefits under uncompensated SDR pricing.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e004","v141-b-g01-e005","v141-b-g01-e006","v141-b-g01-e013","v141-b-g02-E23","v141-b-g03-E13","v141-b-g04-E10","v141-b-g04-E13","v141-b-g04-E15","v141-b-g04-E17"]},"active":true,"source_signature":"fd8f6ce4a2963449401b57568e979bb2a95fa9a0e34b19d7b8654236398106f3","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M01","source_definition":"The ESC manages and adjusts the compensating price included in the local P2P pricing mechanism. Scope: Community P2P energy sharing under modified SDR pricing; compensation adjustment informed by customer assessment. The P2P buying price should not exceed the grid buying price, and the P2P selling price should not fall below the grid selling price. Scope: Buying and selling prices within the P2P sharing community. P2P pricing is conducted 24 h after actual electricity consumption using recorded import/export energy data from smart meters. Scope: Ex-post pricing within the P2P sharing community. P2P trading prices are calculated using the SDR method, with the dynamic supply and demand ratio obtained from aggregated metered supply and demand. Scope: Community P2P trading prices calculated from the previous 24 h of premises' smart-metering data. The compensating price is bounded between zero and the difference between the grid buying and selling prices. Scope: Compensating component of the community's modified SDR pricing mechanism. Both P2P selling and buying prices equal the price of electricity bought from the main grid. Scope: Community P2P buying and selling prices at time t. Condition: SDR^{t} = 0; there is no selling power in the community. Both P2P selling and buying prices equal the grid selling price plus the compensating price. Scope: Community P2P buying and selling prices at time t. Condition: SDR^{t} = 1; community selling power equals buying power.","target_definition":"The ESC administers settlement by calculating individual customer energy bills and ensuring that prosumers’ income balances consumers’ expenditure. Scope: Individual customer settlement in the ESC-operated P2P sharing community. Local P2P pricing determines the electricity bills that prosumers pay or receive as repayments and that consumers pay. Scope: Electricity-bill payments and repayments of prosumers and consumers contracted with the ESC. The source states that the P2P buying-price ceiling implies lower consumer electricity bills under P2P sharing than under P2G trading. Scope: Consumer electricity bills under P2P sharing compared with P2G trading. Condition: The P2P buying price never exceeds the price of electricity bought from the grid. Under this uncompensated pricing case, the source states that prosumer income is undermined while consumers benefit; prosumers may receive less income than without P2P sharing. Scope: The source’s explanation of prosumer income and consumer benefits under uncompensated SDR pricing. Condition: The compensating price is zero and the supply-to-demand ratio exceeds one, so both P2P prices equal the grid selling price. At every studied penetration level, zero compensation is reported to leave some prosumers paying higher electricity bills or receiving lower incomes when participating in P2P sharing. Scope: The reported sensitivity evaluation across the studied penetration levels of PV battery systems. Condition: The compensating price is zero in the reported evaluation. With an appropriate compensating price, modified local SDR pricing is stated to ensure economic benefits for every individual prosumer and consumer, with economic gains described in terms of bill savings or repayments. Scope: Individual prosumer and consumer financial outcomes under modified SDR pricing compared with conventional P2G trading. Condition: The compensating price is appropriately set. Billing is conducted 24 hours after actual electricity consumption using recorded import/export energy data from smart meters, for example half-hourly records. Scope: Customer billing in the proposed two-stage P2P sharing arrangement. The positive value is the amount of electricity bill the prosumer is required to pay. Scope: Prosumer electricity-bill values in the reported financial assessment. Condition: The reported prosumer bill value is positive. The negative value denotes income received by the prosumer. Scope: Prosumer electricity-bill values in the reported financial assessment. Condition: The reported prosumer bill value is negative.","constraints":[{"constraint_id":"v141-c-R007-C003","kind":"logical","role":"core","statement":"The source states that the P2P buying-price ceiling implies lower consumer electricity bills under P2P sharing than under P2G trading. Scope: Consumer electricity bills under P2P sharing compared with P2G trading. Condition: The P2P buying price never exceeds the price of electricity bought from the grid.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g03-E13"]},{"constraint_id":"v141-c-R007-C004","kind":"logical","role":"core","statement":"Under this uncompensated pricing case, the source states that prosumer income is undermined while consumers benefit; prosumers may receive less income than without P2P sharing. Scope: The source’s explanation of prosumer income and consumer benefits under uncompensated SDR pricing. Condition: The compensating price is zero and the supply-to-demand ratio exceeds one, so both P2P prices equal the grid selling price.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E23"]},{"constraint_id":"v141-c-R007-C005","kind":"logical","role":"core","statement":"At every studied penetration level, zero compensation is reported to leave some prosumers paying higher electricity bills or receiving lower incomes when participating in P2P sharing. Scope: The reported sensitivity evaluation across the studied penetration levels of PV battery systems. Condition: The compensating price is zero in the reported evaluation.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g04-E10"]},{"constraint_id":"v141-c-R007-C006","kind":"logical","role":"core","statement":"With an appropriate compensating price, modified local SDR pricing is stated to ensure economic benefits for every individual prosumer and consumer, with economic gains described in terms of bill savings or repayments. Scope: Individual prosumer and consumer financial outcomes under modified SDR pricing compared with conventional P2G trading. Condition: The compensating price is appropriately set.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g04-E15","v141-b-g04-E17"]}],"evidence":[{"evidence_id":"v141-b-g02-E23","location":{"location_id":"src-b91cee592e-p08-c2r3__v141-a-M01-pricing","page":8,"printed_page":null,"section":null,"anchor_text":"prices would dynamically change according to Eqs. (19) and (20). The relation of the P2P buying/sell","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"condition"},"source_text":"When SDR^{t} = 0, there is no selling power in the community, and all the required energy is bought from the main grid. The P2P selling and buying prices are both equal to the price of electricity bought from the grid (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{buy,t}). When SDR^{t} = 1, the selling power is equal to the buying power in the community, and no power is required to import from (or export to) the main grid. The P2P selling and buying prices are both equal to the price of electricity sold to the grid with a compensation (i.e. Pr_{sell}^{t} = Pr_{buy}^{t} = \\lambda_{sell,t} + \\lambda). Here, \\lambda is a compensating price (0 \\le \\lambda \\le \\lambda_{buy,t} - \\lambda_{sell,t}), and it is used to compensate the prosumers to ensure the prosumers be better off when they participate in P2P energy sharing. When 0 \u003c SDR^{t} \u003c 1, or SDR^{t} > 1, the P2P selling and buying prices would dynamically change according to Eqs. (19) and (20). The reason for introducing the compensating price is that, when there is no compensating price (i.e. \\lambda = 0), both P2P selling and buying prices are equal to the price of electricity sold to grid when the SDR is more than 1. This will undermine the prosumers' income, but provide economic benefits to the consumers (i.e. these who do not have PV battery systems). It might happen that the prosumers receive lower incomes than the case of not participating in P2P energy sharing."},{"evidence_id":"v141-b-g03-E13","location":{"location_id":"src-b91cee592e-p11-c1r2__v141-a-M01-participation","page":11,"printed_page":null,"section":null,"anchor_text":"sharing than under the P2G energy trading. Hence, there is no need to ti evaluate the participation ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-11.png","occurrence_role":"condition"},"source_text":"For the consumers, as the P2P buying price (Pr_{buy}^t) is never higher than the price of electricity bought from the grid (\\lambda_{buy,t}), the energy bill of consumers will be always lower when participating in P2P energy sharing than under the P2G energy trading. Hence, there is no need to evaluate the participation willingness of consumers."},{"evidence_id":"v141-b-g04-E10","location":{"location_id":"src-b91cee592e-p14-c1r3__v141-a-M01-participation","page":14,"printed_page":null,"section":null,"anchor_text":"battery, but it only requires to reduce the price of the battery system to ev £430/kWh (only 14% low","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-14.png","occurrence_role":"unknown"},"source_text":"When the compensating price is zero, at all the penetration levels of PV battery systems, some prosumers are paying more electricity bills or gaining lower incomes when participating in P2P energy sharing. This is because the economic beneﬁts were obtained by the consumers, whilst for some of the prosumers, it may not be worth participating in P2P energy sharing."},{"evidence_id":"v141-b-g04-E15","location":{"location_id":"src-b91cee592e-p15-c1r3__v141-a-M01-participation","page":15,"printed_page":null,"section":null,"anchor_text":"pr This paper proposed a two-stage control method to realize P2P energy sharing in community Microgr","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-15.png","occurrence_role":"restatement"},"source_text":"With an appropriate setting of the compensating price, the modiﬁed supply demand ratio based mechanism ensures every individual customer in the community be better oﬀcompared to the conventional P2G energy trading, i.e. every individual prosumer and consumer gain economic beneﬁts. This pricing mechanism can be used as a benchmark applicable to any P2P energy sharing model."},{"evidence_id":"v141-b-g04-E17","location":{"location_id":"src-b91cee592e-p14-c2r3__v141-a-M01-coordination","page":14,"printed_page":null,"section":null,"anchor_text":"to evolutionary algorithms to achieve the global optimum for P2P energy sharing is considered as one","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-14.png","occurrence_role":"exception"},"source_text":"The unfairness of economic gains may exist, i.e. there are diﬀerences in bill savings (or repayments) among consumers (or prosumers)."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Consumer electricity bills under P2P sharing compared with P2G trading. | Customer billing in the proposed two-stage P2P sharing arrangement. | Electricity-bill payments and repayments of prosumers and consumers contracted with the ESC. | Individual customer settlement in the ESC-operated P2P sharing community. | Individual prosumer and consumer financial outcomes under modified SDR pricing compared with conventional P2G trading. | Prosumer electricity-bill values in the reported financial assessment. | The reported sensitivity evaluation across the studied penetration levels of PV battery systems. | The source’s explanation of prosumer income and consumer benefits under uncompensated SDR pricing.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e004","v141-b-g01-e005","v141-b-g01-e006","v141-b-g01-e013","v141-b-g02-E23","v141-b-g03-E13","v141-b-g04-E10","v141-b-g04-E13","v141-b-g04-E15","v141-b-g04-E17"]},"source_record":{"edge_id":"v141-c-R007-E002","source":"pricing.local","target":"settlement.payment","type":"implies","constraint_ids":["v141-c-R007-C003","v141-c-R007-C004","v141-c-R007-C005","v141-c-R007-C006"],"evidence_ids":["v141-b-g02-E23","v141-b-g03-E13","v141-b-g04-E10","v141-b-g04-E15","v141-b-g04-E17"]},"paper_scope_note":"Electricity bill settlement directly depends on the post-metering price; the revenue improvement is a conditional statement and sensitivity case in the paper, not a general proposition independently verified in this work."}}],"assertion_ids":["19-two_stage_battery_sharing::v141-c-R007::E::v141-c-R007-E002"]});
